smoke.fragmentShader:
uniform float uTime;
varying vec2 vUv;
varying float vFar;
varying float vNear;

float fxHash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float fxNoise(vec2 p) {
  vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(fxHash(i), fxHash(i + vec2(1.0, 0.0)), f.x), mix(fxHash(i + vec2(0.0, 1.0)), fxHash(i + vec2(1.0, 1.0)), f.x), f.y);
}
void main() {
  float y = vUv.y;
  float n = fxNoise(vec2(vUv.x * 3.0, y * 6.0 - uTime * 0.55)) * 0.65 + fxNoise(vec2(vUv.x * 7.0 + 1.7, y * 14.0 - uTime * 1.1)) * 0.35;
  float d = abs(vUv.x - 0.5) * 2.0 + (n - 0.5) * 0.8;
  // E399 (mockups B, C): billowing puffs, not a straight slab: the column breaks into clumps as it rises
  float puff = smoothstep(0.35, 0.75, n + 0.25 * (1.0 - y));
  float a = (1.0 - smoothstep(0.15, 0.9, d)) * smoothstep(0.0, 0.06, y) * (1.0 - smoothstep(0.35, 0.95, y)) * puff;
  // Dark grey-brown, lit warm by the fire at its foot and by the afterglow on its lit side.
  vec3 c = mix(vec3(0.3, 0.14, 0.06), vec3(0.024, 0.02, 0.022), smoothstep(0.0, 0.18, y)); // round 8 (mockup C: a grey-brown billow lit orange at its foot, not a dark ghost); round 18 (row 3: near-black, it vanished against the late sky; mockup C's billow reads grey-brown): lifted; round 18b (the lead: too pale, a column up the sky): back toward a dark grey-brown; round 19 (seat C: a fixed colour, 55 against the sky's 16 beside it): lit warm only at its foot where the fire catches it, dark against the night above; round 9: linear values (0.1 displayed as a pale grey column) // a dark plume faintly lit at its foot, or a pale wisp // dark brown-grey, darker than the sky, warm at its foot
  gl_FragColor = vec4(c, a * 0.9 * (1.0 - smoothstep(260.0, 420.0, vFar)) * vNear);
}

